SELECT 'orders' AS table_name, COUNT(*) AS row_count FROM orders
UNION ALL
SELECT 'order_details', COUNT(*) FROM order_details
UNION ALL
SELECT 'pizzas', COUNT(*) FROM pizzas
UNION ALL
SELECT 'pizza_types', COUNT(*) FROM pizza_types;
-- Вывод из таблицы
SELECT *
FROM pizza_types
LIMIT 100;
--загруженность ресторана  в течение недели
WITH
	ORDERS_WEEK AS (
		SELECT
			O.ORDER_ID,
			COUNT(DISTINCT OD.ORDER_ID) AS ORDERS_COUNT,
			SUM(OD.QUANTITY) AS PIZZA_COUNT,
			EXTRACT(
				DOW
				FROM
					O.DATE
			) AS DAY_WEEK
		FROM
			ORDERS O
			JOIN ORDER_DETAILS OD ON O.ORDER_ID = OD.ORDER_ID
		GROUP BY
			O.ORDER_ID
	)
SELECT
	DAY_WEEK,
	SUM(ORDERS_COUNT) AS ORDERS_COUNT_WEEK,
	SUM(PIZZA_COUNT) AS PIZZA_COUNT_WEEK
FROM
	ORDERS_WEEK
GROUP BY
	DAY_WEEK
ORDER BY
	DAY_WEEK;
--час пик
WITH	
    ORDERS_WEEK AS (
		SELECT
			O.ORDER_ID,
			COUNT(DISTINCT OD.ORDER_ID) AS ORDERS_COUNT,
			SUM(OD.QUANTITY) AS PIZZA_COUNT,
			EXTRACT(
				HOUR
				FROM
					O.TIME
			) AS HOUR_DAY
		FROM
			ORDERS O
			JOIN ORDER_DETAILS OD ON O.ORDER_ID = OD.ORDER_ID
		GROUP BY
			O.ORDER_ID
	)
SELECT
	HOUR_DAY,
	SUM(ORDERS_COUNT) AS ORDERS_COUNT_HOUR,
	SUM(PIZZA_COUNT) AS PIZZA_COUNT_HOUR
FROM
	ORDERS_WEEK
GROUP BY
	HOUR_DAY
ORDER BY
	HOUR_DAY;
--среднее количество пицц в заказе
WITH
	ORDER_DATE_PIZZA AS (
		SELECT
			O.ORDER_ID,
			O.DATE AS ORDER_DATE,
			SUM(OD.QUANTITY) AS PIZZA_PER_ORDER,
			AVG(SUM(OD.QUANTITY)) OVER () AS AVG_PIZZA_ALL_DAYS
		FROM
			ORDERS O
			JOIN ORDER_DETAILS OD ON O.ORDER_ID = OD.ORDER_ID
		GROUP BY
			O.ORDER_ID
	)
SELECT
	ORDER_DATE,
	COUNT(ORDER_ID) ORDERS_PER_DAY,
	SUM(PIZZA_PER_ORDER) AS PIZZA_PER_DAY,
	ROUND(AVG(PIZZA_PER_ORDER), 1) AS PIZZA_PER_ORDER_AVG,
	MAX(AVG_PIZZA_ALL_DAYS) AS AVG_PIZZA_ALL_DAYS
FROM
	ORDER_DATE_PIZZA
GROUP BY
	ORDER_DATE
ORDER BY
	ORDER_DATE;
--анализ ассортимента (Самые популярные и непопулярные пиццы)
SELECT
	PT.NAME,
	PT.CATEGORY,
	COUNT(DISTINCT OD.ORDER_ID) AS COUNT_PIZZA_ORDERS,
	SUM(OD.QUANTITY) AS SUM_PIZZA_ORDERS
FROM
	PIZZA_TYPES PT
	LEFT JOIN PIZZAS P ON PT.PIZZA_TYPE_ID = P.PIZZA_TYPE_ID
	LEFT JOIN ORDER_DETAILS OD ON P.PIZZA_ID = OD.PIZZA_ID
GROUP BY
	PT.NAME,
	PT.CATEGORY
ORDER BY
	PT.CATEGORY,
	SUM_PIZZA_ORDERS DESC;
--анализ категорий
SELECT
	PT.CATEGORY,
	SUM(OD.QUANTITY) AS SUM_PIZZA_ORDERS,
	COUNT(DISTINCT OD.ORDER_ID) AS COUNT_PIZZA_ORDERS,
	ROUND(
		100.0 * SUM(OD.QUANTITY) / SUM(SUM(OD.QUANTITY)) OVER (),
		2
	) AS CATEGORY_SHARE
FROM
	PIZZA_TYPES PT
	LEFT JOIN PIZZAS P ON PT.PIZZA_TYPE_ID = P.PIZZA_TYPE_ID
	LEFT JOIN ORDER_DETAILS OD ON P.PIZZA_ID = OD.PIZZA_ID
GROUP BY
	PT.CATEGORY
ORDER BY
	CATEGORY_SHARE DESC;
--анализ размеров пицц
SELECT
	P.SIZE,
	COUNT(DISTINCT OD.ORDER_ID) AS COUNT_SIZE_ORDERS,
	SUM(OD.QUANTITY) AS SUM_SIZE_ORDERS,
	ROUND(
		100.0 * SUM(OD.QUANTITY) / SUM(SUM(OD.QUANTITY)) OVER (),
		2
	) AS SIZE_SHARE
FROM
	PIZZAS P
	LEFT JOIN ORDER_DETAILS OD ON P.PIZZA_ID = OD.PIZZA_ID
GROUP BY
	P.SIZE
ORDER BY
	P.SIZE;
--анализ выручки по каждому размеру пиццы
SELECT
	P.SIZE,
	SUM(P.PRICE * OD.QUANTITY) AS REVENUE_SIZE
FROM
	PIZZAS P
	LEFT JOIN ORDER_DETAILS OD ON P.PIZZA_ID = OD.PIZZA_ID
GROUP BY
	P.SIZE
ORDER BY
	P.SIZE;
--анализ выручки по каждой категории
SELECT
	PT.CATEGORY,
	SUM(P.PRICE * OD.QUANTITY) AS REVENUE_CATEGORY
FROM
	PIZZAS P
	LEFT JOIN ORDER_DETAILS OD ON P.PIZZA_ID = OD.PIZZA_ID
	LEFT JOIN PIZZA_TYPES PT ON PT.PIZZA_TYPE_ID = P.PIZZA_TYPE_ID
GROUP BY
	PT.CATEGORY
ORDER BY
	REVENUE_CATEGORY DESC;
-- средняя цена пиццы по категориям
SELECT
	PT.CATEGORY,
	MIN(P.PRICE) AS MIN_PRICE_ALL_PIZZAS,
	MAX(P.PRICE) AS MAX_PRICE_ALL_PIZZAS,
	ROUND(AVG(PRICE), 2) AS AVG_PRICE_ALL_PIZZAS
FROM
	PIZZAS P
	LEFT JOIN PIZZA_TYPES PT ON PT.PIZZA_TYPE_ID = P.PIZZA_TYPE_ID
GROUP BY
	PT.CATEGORY
ORDER BY
	PT.CATEGORY;
--10 пицц с наибольшей выручкой
SELECT
	PT.NAME,
	PT.CATEGORY,
	SUM(P.PRICE * OD.QUANTITY) AS REVENUE_PER_PIZZA_TYPE
FROM
	PIZZAS P
	LEFT JOIN ORDER_DETAILS OD ON P.PIZZA_ID = OD.PIZZA_ID
	LEFT JOIN PIZZA_TYPES PT ON PT.PIZZA_TYPE_ID = P.PIZZA_TYPE_ID
GROUP BY
	PT.NAME,
	PT.CATEGORY
ORDER BY
	REVENUE_PER_PIZZA_TYPE DESC
LIMIT
	10;
--10 пицц по количеству
SELECT
	PT.NAME,
	PT.CATEGORY,
	SUM(OD.QUANTITY) AS COUNT_PER_PIZZA_TYPE
FROM
	PIZZAS P
	LEFT JOIN ORDER_DETAILS OD ON P.PIZZA_ID = OD.PIZZA_ID
	LEFT JOIN PIZZA_TYPES PT ON PT.PIZZA_TYPE_ID = P.PIZZA_TYPE_ID
GROUP BY
	PT.NAME,
	PT.CATEGORY
ORDER BY
	COUNT_PER_PIZZA_TYPE DESC
LIMIT
	10;
--выручка по месяцам и средний чек
WITH
	REVENUE_ORDER_TABLE AS (
		SELECT
			EXTRACT(MONTH FROM O.DATE) AS MONTH_ORDER,
			COUNT(DISTINCT O.ORDER_ID) AS COUNT_ORDERS_PER_MONTH,
			LAG(SUM(OD.QUANTITY * P.PRICE)) OVER (ORDER BY EXTRACT(MONTH FROM O.DATE)) AS PREVIOUS_REVENUE_ORDER,
			SUM(OD.QUANTITY * P.PRICE) AS REVENUE_ORDER			
		FROM
			PIZZAS P
			JOIN ORDER_DETAILS OD ON P.PIZZA_ID = OD.PIZZA_ID
			JOIN ORDERS O ON OD.ORDER_ID = O.ORDER_ID
		GROUP BY MONTH_ORDER
	),
    MONTHLY_REVENUE AS (
    SELECT
        MONTH_ORDER,
        COUNT(ORDER_ID) AS COUNT_ORDERS_PER_MONTH,
        SUM(REVENUE_ORDER) AS REVENUE_PER_MONTH,
        ROUND(AVG(REVENUE_ORDER), 2) AS AVG_ORDER_PER_MONTH
    FROM ORDER_REVENUE
    GROUP BY MONTH_ORDER
)
SELECT
	rot.MONTH_ORDER,
	rot.COUNT_ORDERS_PER_MONTH,
	rot.PREVIOUS_REVENUE_ORDER,
	rot.REVENUE_ORDER,
	rot.REVENUE_ORDER - rot.PREVIOUS_REVENUE_ORDER AS ABS_RAZNICA,
	ROUND(((rot.REVENUE_ORDER - rot.PREVIOUS_REVENUE_ORDER) / rot.PREVIOUS_REVENUE_ORDER) * 100.0,
		1) AS OTN_RAZNICA,
	mr.avg_order_per_month
FROM
	REVENUE_ORDER_TABLE rot
	JOIN MONTHLY_REVENUE mr on rot.MONTH_ORDER = mr.MONTH_ORDER
ORDER BY
	MONTH_ORDER;
--анализ динамики заказов
WITH
	ORDER_REVENUE AS (
		SELECT
			EXTRACT(
				MONTH
				FROM
					O.DATE
			) AS MONTH_ORDER,
			SUM(OD.QUANTITY * P.PRICE) AS REVENUE_ORDER,
			OD.ORDER_ID
		FROM
			PIZZAS P
			JOIN ORDER_DETAILS OD ON P.PIZZA_ID = OD.PIZZA_ID
			JOIN ORDERS O ON OD.ORDER_ID = O.ORDER_ID
		GROUP BY
			MONTH_ORDER,
			OD.ORDER_ID
	),
	MONTHLY_REVENUE AS (
		SELECT
			MONTH_ORDER,
			COUNT(ORDER_ID) AS COUNT_ORDERS_PER_MONTH,
			SUM(REVENUE_ORDER) AS REVENUE_PER_MONTH,
			ROUND(AVG(REVENUE_ORDER), 2) AS AVG_ORDER_PER_MONTH
		FROM
			ORDER_REVENUE
		GROUP BY
			MONTH_ORDER
	)
SELECT
	MR.MONTH_ORDER,
	MR.COUNT_ORDERS_PER_MONTH,
	LAG(MR.REVENUE_PER_MONTH) OVER (
		ORDER BY
			MR.MONTH_ORDER
	) AS PREVIOUS_REVENUE_ORDER,
	MR.REVENUE_PER_MONTH,
	MR.REVENUE_PER_MONTH - LAG(MR.REVENUE_PER_MONTH) OVER (
		ORDER BY
			MR.MONTH_ORDER
	) AS ABS_RAZNICA,
	ROUND(
		(
			(
				MR.REVENUE_PER_MONTH - LAG(MR.REVENUE_PER_MONTH) OVER (
					ORDER BY
						MR.MONTH_ORDER
				)
			) / LAG(MR.REVENUE_PER_MONTH) OVER (
				ORDER BY
					MR.MONTH_ORDER
			)
		) * 100.0,
		1
	) AS OTN_RAZNICA,
	MR.AVG_ORDER_PER_MONTH
FROM
	MONTHLY_REVENUE MR
ORDER BY
	MONTH_ORDER


















